    private static ProfileStore Store(string name,Action<string>? fault=null)=>new(Path.Combine(Environment.GetEnvironmentVariable("MISTSEA_TEST_OUTPUT")??Path.GetTempPath(),"chapter-six-"+name+"-"+Guid.NewGuid()),Catalog.ReleaseId,fault);
    private static void Success(CommandResult result)=>Require(result.Status is CommitStatus.Committed or CommitStatus.AlreadyCommitted,StrictJson.Serialize(result));
    private static T Read<T>(ProfileStore s,string id)=>StrictJson.Deserialize<T>(Done(s.SnapshotAsync()).Entities.Single(x=>x.Id==id).Json);
    public sealed class CheckpointArchive(ProfileStore store):IEndingCheckpointArchive
