    private static void VesselWalk(ProfileStore s,VesselInteriorService interior,Point2 to){var a=Read<ActorState>(s,"actor");var path=new NavigationGrid(interior.Geometry[a.Scene]).FindPath(a.Position,to,true);Require(path.Length>0);Success(Done(interior.MoveAsync(path)));}
    private static void Chart(ProfileStore s,VesselInteriorService interior){if(Read<ActorState>(s,"actor").Scene=="HUB-S01"){var p=interior.Geometry["HUB-S01"].Ports.Single(x=>x.TargetScene=="HUB-S02");VesselWalk(s,interior,p.Stand);Success(Done(interior.EnterPortAsync(p.Id)));}VesselWalk(s,interior,interior.Geometry["HUB-S02"].Spots.Single(x=>x.Id=="HUB-S02.chart").Stand);}
    public static (ChapterSixService Service,VesselInteriorService Interior,CheckpointArchive Archive) ActualArrival(ProfileStore s)
    {var (prior,old)=ChapterFive.ChapterFiveCases.NormalComplete(s);var r=new ChapterFive.ChapterFiveCases.Run(s,prior);r.At("R5-S01.berth");var package=Package();var geo=old.Geometry.SetItems(Done(prior.CurrentGeometryAsync())).SetItems(package.Scenes.ToDictionary(x=>x.Geometry.Id,x=>x.Geometry));var archive=new CheckpointArchive(s);var service=new ChapterSixService(s,Catalog,package,geo,archive);var interior=new VesselInteriorService(s,Catalog,old.Package,geo);var board=Done(interior.PreviewBoardAsync());Require(board.Ready,StrictJson.Serialize(board));Success(Done(interior.ConfirmPreviewAsync(board.Token)));Chart(s,interior);var voyage=new RegionalVoyageService(s,Catalog,VoyageDefinition(),interior.Geometry);var p=Done(voyage.VerifyAndRegisterAsync());Success(p.RouteProof);Success(p.BerthProof);Success(p.Registration.Route);Success(p.Registration.Berth);Success(Done(voyage.SailAsync("R6")));Success(Done(voyage.RecordArrivalAsync()));Done(service.InitializeRegionAsync());return(service,interior,archive);}
    public static (ChapterSixService Service,VesselInteriorService Interior,CheckpointArchive Archive) NormalPrepared(ProfileStore s,bool enhanced=false)
    {var p=ActualArrival(s);var r=new Run(s,p.Service,p.Interior);r.Node601();r.RidgeReady();r.Base("R6");r.Node603();foreach(string region in new[]{"R5","R4","R3","R2","R1"}){r.Sail(region);r.PriorAt(p.Service.Package.Facilities.Single(f=>f.Region==region).PhysicalSpot);r.Base(region);}r.Sail("R6");r.Node602();if(enhanced)r.Enhanced();r.DepartureReady();return p;}
    public static (ChapterSixService Service,VesselInteriorService Interior,CheckpointArchive Archive) NormalComplete(ProfileStore s,bool enhanced=false)
    {var p=NormalPrepared(s,enhanced);var r=new Run(s,p.Service,p.Interior);Success(Done(p.Service.SealPreparationAsync()));r.Board();var launch=new FinaleLaunchService(s,Catalog,p.Interior.Package,Finale(),p.Archive);var preview=Done(launch.PreviewAsync());Require(preview.Ready,StrictJson.Serialize(preview));Success(Done(launch.ConfirmAsync(preview.Token)));return p;}
    public sealed class Run(ProfileStore store,ChapterSixService service,VesselInteriorService interior)
    {
        public ChapterSixService Service=>service;public ChapterSixView View=>Done(service.ViewAsync());
        public void Spot(string spot){var v=View;var to=v.Geometry[v.Actor.Scene].Spots.Single(x=>x.Id==spot).Stand;var path=new NavigationGrid(v.Geometry[v.Actor.Scene]).FindPath(v.Actor.Position,to,true);Require(path.Length>0);Done(service.TraverseAsync(path));}
        public void Exit(string to){var v=View;var p=v.Geometry[v.Actor.Scene].Ports.Single(x=>x.TargetScene==to);Done(service.TraverseAsync(new NavigationGrid(v.Geometry[v.Actor.Scene]).FindPath(v.Actor.Position,p.Stand,true)));Success(Done(service.EnterPortAsync(p.Id)));}
        public void Goto(string scene){var snap=View.Snapshot;var start=Read<ActorState>(store,"actor").Scene;var previous=PathTo(start,scene,View.Geometry,(from,p)=>service.PortIssue(Project(snap,Read<ActorState>(store,"actor") with{Scene=from}),p));foreach(var step in previous)Exit(step);}
        public void At(string spot){Goto(spot.Split('.')[0]);Spot(spot);}
        private static BranchSnapshot Project(BranchSnapshot s,ActorState a)=>s with{Entities=s.Entities.Select(e=>e.Id=="actor"?e with{Json=StrictJson.Serialize(a)}:e).ToImmutableArray()};
        private static string[] PathTo(string from,string to,IReadOnlyDictionary<string,SceneGeometry> geo,Func<string,Port,string?> gate){var seen=new Dictionary<string,string?>{{from,null}};var queue=new Queue<string>();queue.Enqueue(from);while(queue.TryDequeue(out var current)){if(current==to)break;foreach(var p in geo[current].Ports)if(geo.ContainsKey(p.TargetScene)&&gate(current,p) is null&&seen.TryAdd(p.TargetScene,current))queue.Enqueue(p.TargetScene);}Require(seen.ContainsKey(to),"no actual current paired route to "+to);var path=new List<string>();for(string? c=to;c!=from;c=seen[c!])path.Add(c!);path.Reverse();return path.ToArray();}
        public void Material(string id){var m=service.Package.Materials.Single(x=>x.Id==id);At(m.Spot);Success(Done(service.DiscoverAsync(id)));}
        public void ReadQuest(string q){foreach(var m in service.Package.Materials.Where(x=>x.Quest==q&&x.Kind!="listening_script"))Material(m.Id);}
        public void Act(string action){At(service.Package.Stations.Single(x=>x.Action==action).Spot);Success(Done(service.PerformAsync(action)));}
        public void Meaning(string q,params (string Key,string Value)[] fields){var t=service.Package.WritingTasks.Single(x=>x.Quest==q);At(t.Spot);var old=Done(store.GetDraftAsync(t.Id));Done(service.SaveDraftAsync(t.Id,old?.Revision??0,old?.Id,"Candidate engineering prose. Explicit structured interpretation follows actual observations and does not claim a human language score."));Success(Done(service.ConfirmMeaningAsync(q,fields.ToImmutableDictionary(x=>x.Key,x=>x.Value),true)));}
        public ChapterSixPreview Submit(string q){At(service.SubmissionSpot(q));var p=Done(service.PreviewSubmissionAsync(q));Require(p.Ready,StrictJson.Serialize(p));Success(Done(service.ConfirmPreviewAsync(p.Token)));return p;}
        public void Battle(string id){At(id switch{"ENC-R6-01"=>"R6-S03.pass_entry","ENC-R6-02"=>"R6-S04.station_entry","ENC-R6-03"=>"R6-S05.first_entry","ENC-R6-04"=>"R6-S06.outer_entry",_=>"R6-S07.platform"});Success(Done(service.BeginEncounterAsync(id)));for(int n=0;n<900&&Done(service.EncounterAsync(id))!.Battle.Outcome==CombatOutcome.Active;n++){var p=Done(service.PreviewEncounterActionAsync(id,BattleCandidate.Choose(new(service.BattleDefinitions,Done(service.EncounterAsync(id))!.Battle))));Require(p.Action.Legal,p.Description);Success(Done(service.ConfirmPreviewAsync(p.Token)));}Require(Done(service.EncounterAsync(id))!.Battle.Outcome==CombatOutcome.Controlled,"actual R6 encounter failed "+id);}
        public void Node601(bool submit=true){Material("R6-Q601-R-LANDING");Act("register_landing");Material("R6-Q601-R-BRIEFING");Act("request_survey");Act("inspect_basic_gear");Material("R6-Q601-R-FORECAST");At("R6-S03.forecast");Success(Done(service.ChooseCorridorAsync("marked_leeward")));Act("secure_guide_markers");Battle("ENC-R6-01");Material("R6-Q601-R-INSTRUMENT");Material("R6-Q601-R-RISK");Battle("ENC-R6-02");Act("isolate_survey_instrument");At("R6-S04.calibration");Success(Done(service.ConfigureSurveyAsync("Z",0,"R",10,"current_overload_amplification","current_survey_stage")));Act("test_survey");Material("R6-Q601-R-RETURN");Act("inspect_inner_return");Meaning("Q-601",("risk","current_overload_amplification"),("supply","bounded_essential"),("window","current_survey_stage"),("return","inspected_inner_route"),("causality","all_fog_not_proven"));if(submit)Submit("Q-601");}
        public void RidgeReady(){Material("R6-Q603-R-MANIFEST");Act("inspect_cargo_manifest");Material("R6-Q603-R-SEGMENTS");At("R6-S05.segment");var cargo=Read<FrontierCargoState>(store,"R6:cargo");Success(Done(service.PlanCargoAsync(cargo.ItemIds.ToArray(),["ROLE-R6-CART-DRIVER","ROLE-R6-CARGO-WATCH"],"R6-S07","previous_safe_segment")));Battle("ENC-R6-03");Act("start_outer_segment");Exit("R6-S06");Battle("ENC-R6-04");Act("continue_ridge_segment");Exit("R6-S07");Material("R6-Q603-R-PLATFORM");At("R6-S07.field_device");foreach(string step in new[]{"disconnect_field_input","fix_external_brake","verify_zero_field_energy"})Success(Done(service.ControlFieldDeviceAsync(step)));Act("protect_current_cargo");Battle("ENC-R6-05");Act("isolate_platform");Material("R6-Q603-R-LOCAL");Act("receive_base_packet");Act("inspect_ridge_return");Act("test_ridge_tower");}
        public void Base(string region){if(region=="R4")Success(Done(service.ReinspectCurrentFacilitySafetyAsync(region)));var f=service.Package.Facilities.Single(x=>x.Region==region);if(region=="R6")At(f.PhysicalSpot);var rules=new EngineeringRules(Catalog);var sources=rules.Sources.Values.Where(x=>x.Id.StartsWith("BASE-"+f.Tower+"-",StringComparison.Ordinal)).ToArray();var ids=sources.SelectMany(x=>Enumerable.Range(1,x.Quantity).Select(n=>"R6-finite:"+x.Id+":"+n)).ToArray();Success(Done(service.InspectFacilityAsync(region,f.Version,f.Installer,f.WatchPosts.ToArray(),ids)));Success(Done(service.RegisterFacilityTeamAsync(region)));Success(Done(service.RegisterCurrentFacilitySafetyAsync(region)));foreach(var src in sources){var serials=Enumerable.Range(1,src.Quantity).Select(n=>"R6-finite:"+src.Id+":"+n).ToArray();Success(Done(service.InspectProcurementStepAsync(src.Id,1,"match_contract_serials",serials)));Success(Done(service.InspectProcurementStepAsync(src.Id,2,"check_and_deliver_components",serials)));}Work(region,WorkType.BaselineCheck,WorkOrderService.Preparation);}
        public void Work(string region,WorkType type,string version){Success(Done(service.ReserveWorkAsync(region,type,version)));string[] stages=["transport_reserved_components","check_delivered_components","install_declared_configuration","verify_current_local_work"];for(int i=1;i<=4;i++)Success(Done(service.ExecuteWorkStepAsync(region,type,i,stages[i-1])));}
        public void Node603(){ReadQuest("Q-603");Meaning("Q-603",("destination","R6-S07"),("components","four_actual_base_serials"),("escorts","two_declared_local_posts"),("fallback","previous_safe_segment"),("enhanced","not_granted"));Submit("Q-603");}
        public void Node602(){ReadQuest("Q-602");Meaning("Q-602",("baseline","six_actual_verified"),("enhanced","current_receipts_not_assumed"),("private_resources","separate"),("policy","not_selected"));Submit("Q-602");}
        private void PriorNavigate(string scene,Point2? point,string? spot){var a=Read<ActorState>(store,"actor");string region=a.Scene[..2];ImmutableDictionary<string,SceneGeometry> geo;Action<ImmutableArray<Point2>> move;Func<string,CommandResult> enter;Func<BranchSnapshot,Port,string?> gate;
         if(region=="R1"){var kernel=new ChapterOneService(store,Catalog,ChapterOne.ChapterOneCases.Package(),interior.Geometry);geo=kernel.Geometry;move=p=>Done(kernel.MoveAsync(p));enter=id=>Done(kernel.EnterPortAsync(id));gate=kernel.PortIssue;}
         else if(region=="R2"){var kernel=new ChapterTwoService(store,Catalog,ChapterTwo.ChapterTwoCases.Package());geo=Done(kernel.CurrentGeometryAsync());move=p=>Done(kernel.TraverseAsync(p));enter=id=>Done(kernel.EnterPortAsync(id));gate=kernel.PortIssue;}
         else if(region=="R3"){var kernel=new ChapterThreeService(store,Catalog,ChapterThree.ChapterThreeCases.Package());geo=Done(kernel.CurrentGeometryAsync());move=p=>Done(kernel.TraverseAsync(p));enter=id=>Done(kernel.EnterPortAsync(id));gate=kernel.PortIssue;}
         else if(region=="R4"){var kernel=new ChapterFourService(store,Catalog,ChapterFour.ChapterFourCases.Package());geo=Done(kernel.CurrentGeometryAsync());move=p=>Done(kernel.TraverseAsync(p));enter=id=>Done(kernel.EnterPortAsync(id));gate=kernel.PortIssue;}
         else{var kernel=new ChapterFiveService(store,Catalog,ChapterFive.ChapterFiveCases.Package());geo=Done(kernel.CurrentGeometryAsync());move=p=>Done(kernel.TraverseAsync(p));enter=id=>Done(kernel.EnterPortAsync(id));gate=kernel.PortIssue;}
         var snap=Done(store.SnapshotAsync());foreach(var next in PathTo(a.Scene,scene,geo,(from,p)=>gate(Project(snap,a with{Scene=from}),p))){a=Read<ActorState>(store,"actor");var p=geo[a.Scene].Ports.Single(x=>x.TargetScene==next);move(new NavigationGrid(geo[a.Scene]).FindPath(a.Position,p.Stand,region!="R1"));Success(enter(p.Id));}a=Read<ActorState>(store,"actor");var target=point??geo[scene].Spots.Single(x=>x.Id==spot).Stand;move(new NavigationGrid(geo[scene]).FindPath(a.Position,target,region!="R1"));}
        public void PriorAt(string spot)=>PriorNavigate(spot.Split('.')[0],null,spot);
        public void Board(){var actor=Read<ActorState>(store,"actor");var berth=Read<VesselBerth>(store,"berth:"+Read<SharedVessel>(store,"ship:glimmer").DockRegion);if(actor.Scene.StartsWith("R6",StringComparison.Ordinal)){Goto(berth.Scene);var p=new NavigationGrid(View.Geometry[berth.Scene]).FindPath(View.Actor.Position,berth.Boarding,true);Done(service.TraverseAsync(p));}else PriorNavigate(berth.Scene,berth.Boarding,null);var board=Done(interior.PreviewBoardAsync());Require(board.Ready,StrictJson.Serialize(board));Success(Done(interior.ConfirmPreviewAsync(board.Token)));Chart(store,interior);}
