        public void DepartureReady(){ReadQuest("Q-604");Act("inspect_departure_qualification");At("R6-S08.qualification");Success(Done(service.ConfirmPreparationDirectionAsync("accept_base_directions")));Meaning("Q-604",("policy","not_selected"),("risks","current_handed_over"),("preparation","accept_base_directions"));At("R6-S08.commitments");Success(Done(service.VerifyRiskRegisterAsync()));At("R6-S08.qualification");}
        public void Enhanced(){At("R6-S08.technical");Success(Done(service.VerifyTechnicalPackageAsync("C",40,"limited","retained_failures_and_current_bounded_success")));var rules=new EngineeringRules(Catalog);foreach(string region in new[]{"R4","R3","R2","R1","R6"}){if(Read<ActorState>(store,"actor").Scene[..2]!=region)Sail(region);var f=service.Package.Facilities.Single(x=>x.Region==region);if(region=="R6")At(f.PhysicalSpot);else PriorAt(f.PhysicalSpot);foreach(var src in rules.Sources.Values.Where(x=>x.Region==region&&!x.Id.StartsWith("BASE-",StringComparison.Ordinal))){string[] steps=src.Id switch{"SUP-CTRL"=>["inspect_retained_technical_record","match_controller_serials","local_controller_acceptance","deliver_accepted_controllers"],"SUP-COUP"=>["inspect_retained_spare_scope","match_coupler_serials","local_coupler_acceptance","deliver_accepted_couplers"],"SUP-TEST"=>["inspect_fixture_dedication","check_independent_fixture_serials","deliver_reusable_fixtures"],_=>["inspect_transition_stock","check_protected_supply_boundary","deliver_transition_crates"]};var ids=Enumerable.Range(1,src.Quantity).Select(n=>"R6-finite:"+src.Id+":"+n).ToArray();for(int i=1;i<=steps.Length;i++)Success(Done(service.InspectProcurementStepAsync(src.Id,i,steps[i-1],ids)));}}
         foreach(string region in new[]{"R5","R4","R3","R2","R1","R6"}){if(Read<ActorState>(store,"actor").Scene[..2]!=region)Sail(region);var f=service.Package.Facilities.Single(x=>x.Region==region);if(region=="R6")At(f.PhysicalSpot);else PriorAt(f.PhysicalSpot);Work(region,WorkType.EnhancedInstall,ChapterSixService.TechnicalVersion);Work(region,WorkType.TransitionSupply,WorkOrderService.Preparation);Success(Done(service.GrantLocalTrialAsync(region,ChapterSixService.TechnicalVersion,f.WatchPosts.ToArray())));Success(Done(service.ReserveWorkAsync(region,WorkType.FieldTrial,ChapterSixService.TechnicalVersion)));string[] stages=["transport_reserved_components","check_delivered_components","install_declared_configuration"];for(int i=1;i<=3;i++)Success(Done(service.ExecuteWorkStepAsync(region,WorkType.FieldTrial,i,stages[i-1])));Success(Done(service.FieldTrialStepAsync(region,"inspect_isolation_backup","bounded_local_preservation",true,true,true)));Success(Done(service.FieldTrialStepAsync(region,"verify_bounded_local_output","bounded_local_preservation",true,true,true)));Success(Done(service.ExecuteWorkStepAsync(region,WorkType.FieldTrial,4,"verify_current_local_work")));foreach(var role in new[]{Mist.Application.Factions.MandateRole.Operator,Mist.Application.Factions.MandateRole.Representative})Success(Done(service.SignRegionalProtocolAsync(region,role,"ROLE-"+region+(role==Mist.Application.Factions.MandateRole.Operator?"-OP":"-REP"),(role==Mist.Application.Factions.MandateRole.Operator?"operate:":"represent:")+region,["essential_protection","bounded_contact","mutual_aid","independent_review"])));}}
