    public static void Register()
    {
        Add("CP-R6-03","Committed physical procurement resumes after an actual after-commit failure and rejects a different finite batch",()=>
        {
            string profile,sourceId,resource;int quantity;string[] ids;ImmutableDictionary<string,SceneGeometry> geometry;
            bool armed=false;using(var s=Store("procurement-crash",point=>{if(armed&&point=="after_commit"){armed=false;throw new IOException("Injected process boundary after physical proof committed, before engineering consumer.");}}))
            {
                var p=ActualArrival(s);var r=new Run(s,p.Service,p.Interior);r.Node601();r.RidgeReady();r.At("R6-S07.delivery");var f=p.Service.Package.Facilities.Single(x=>x.Region=="R6");var sources=p.Service.Engineering.Rules.Sources.Values.Where(x=>x.Id.StartsWith("BASE-"+f.Tower+"-",StringComparison.Ordinal)).ToArray();var source=sources.Single(x=>x.Resource=="base_isolator");sourceId=source.Id;resource=source.Resource;quantity=source.Quantity;ids=Enumerable.Range(1,quantity).Select(n=>"R6-finite:"+sourceId+":"+n).ToArray();var all=sources.SelectMany(x=>Enumerable.Range(1,x.Quantity).Select(n=>"R6-finite:"+x.Id+":"+n)).ToArray();Success(Done(p.Service.InspectFacilityAsync("R6",f.Version,f.Installer,f.WatchPosts.ToArray(),all)));Success(Done(p.Service.InspectProcurementStepAsync(sourceId,1,"match_contract_serials",ids)));
                armed=true;Throws<IOException>(()=>Done(p.Service.InspectProcurementStepAsync(sourceId,2,"check_and_deliver_components",ids)));var interrupted=Done(s.SnapshotAsync());Require(Read<ProcurementProgress>(s,"procurement:"+sourceId) is{Step:1,Delivered:false}&&interrupted.Balances.GetValueOrDefault(EngineeringRules.Available(resource))==0&&ids.All(id=>interrupted.Items.Single(i=>i.Id==id) is{OwnerKind:"consumed"} i&&i.OwnerId=="engineering-stock:"+sourceId)&&interrupted.Receipts.Count(x=>x.SemanticKey=="R6:physical-procurement:"+sourceId+":2")==1);
                var different=sources.Single(x=>x.Resource=="local_backup");string[] wrong=Enumerable.Range(1,different.Quantity).Select(n=>"R6-finite:"+different.Id+":"+n).ToArray();long seq=interrupted.Sequence;Throws<InvalidOperationException>(()=>Done(p.Service.InspectProcurementStepAsync(sourceId,2,"check_and_deliver_components",wrong)));Require(Done(s.SnapshotAsync()).Sequence==seq&&wrong.All(id=>Done(s.SnapshotAsync()).Items.Single(i=>i.Id==id).OwnerKind=="warehouse"));profile=s.RootPath;geometry=p.Interior.Geometry;
            }
            using var reopened=new ProfileStore(profile,Catalog.ReleaseId);var service=new ChapterSixService(reopened,Catalog,Package(),geometry,new CheckpointArchive(reopened));Success(Done(service.InspectProcurementStepAsync(sourceId,2,"check_and_deliver_components",ids)));var recovered=Done(reopened.SnapshotAsync());Require(Read<ProcurementProgress>(reopened,"procurement:"+sourceId) is{Step:2,Delivered:true}&&recovered.Balances.GetValueOrDefault(EngineeringRules.Available(resource))==quantity&&recovered.Receipts.Count(x=>x.SemanticKey=="R6:physical-procurement:"+sourceId+":2")==1&&recovered.Receipts.Count(x=>x.SemanticKey=="procurement:"+sourceId+":step:2")==1);long recoveredSequence=recovered.Sequence;Success(Done(service.InspectProcurementStepAsync(sourceId,2,"check_and_deliver_components",ids)));Require(Done(reopened.SnapshotAsync()).Sequence==recoveredSequence&&Done(reopened.SnapshotAsync()).Balances.GetValueOrDefault(EngineeringRules.Available(resource))==quantity&&recovered.Receipts.All(r=>!r.SemanticKey.StartsWith("fixture:",StringComparison.Ordinal)));
        });
        Add("CP-R6-05","Actual zero-XP predecessor and R5R6 arrival produce an untouched native entry with persistent normal receipts",()=>
        {
            using var s=Store("native-entry");var p=ActualArrival(s);var v=Done(p.Service.ViewAsync());Require(v.Actor.Scene=="R6-S01"&&v.Actor.Position==new Point2(48,90)&&v.Snapshot.Balances["experience"]==10500&&v.Materials.Length==0&&!v.State.Landing&&!v.State.Briefing&&!v.State.SurveyReported&&!v.State.CargoDelivered&&v.Snapshot.Balances.Where(x=>x.Key.StartsWith("engineering:",StringComparison.Ordinal)).All(x=>x.Value==0)&&v.Snapshot.Receipts.All(r=>!r.SemanticKey.StartsWith("fixture:",StringComparison.Ordinal)&&!r.SemanticKey.StartsWith("internal:",StringComparison.Ordinal)&&r.ActionType is not("explicit_engineering_fixture" or "internal_slice_initialization")));Done(s.CreateCheckpointAsync("manual"));File.WriteAllText(Path.Combine(Path.GetDirectoryName(s.MainPath)!,"normal-r6-native-entry.json"),StrictJson.Serialize(new{scope="actual zero-XP through Q504 and typed R5R6 voyage; R6 initialized only, with no local material, device, transport, engineering or reward action",experience=10500,profile_path=s.MainPath,actor=v.Actor,receipts=v.Snapshot.Receipts,native_human="pending",physical_ime="not_run",language_review="human_pending",audio="source-bound candidate bindings separate; no playback occurred in this SQLite entry"}));
